# Generated by sync_menu_ui; edit canonical sources.
"""The PROFILES page (decisions of 2026-10-12, mockup docs/mokup/menu_mods/profils/3_page.png): one row per saved
profile, its switch, EDIT and DELETE, its keyboard key on the right and its five values under it. DELETE asks first, in
a pop-up with CANCEL and DELETE (4_supprimer.png).

Rows are drawn for the most profiles there can be and collapsed past the saved ones: a profile saved while the menu is
open shows without drawing the menu again. Apex Movement shows the card in an Options tab (panel_options.py), the other
camera mods in a sidebar page (page below); the page at work is panel_profile_list.py.
"""

from . import panel_buttons as b, panel_camera_commands as commands, panel_pages as p, panel_popup as popup
from . import panel_text as tx, panel_theme as t, panel_widgets as w

try:
    from .apex_camera_runtime.profile_store import MAX_PROFILES
except ModuleNotFoundError as error:
    if error.name != f"{__package__}.apex_camera_runtime":
        raise
    from apex_camera_runtime.profile_store import MAX_PROFILES

PAGE = "profiles"
POPUP = "profile_delete"
# A row's buttons: name, kind and first look; the switch is painted by the profile it shows (panel_profile_list.py).
BUTTONS = (("switch", "switch", "off"), ("edit", "action", "secondary"), ("delete", "action", "off"))


def card(body, widgets, template):
    rows = p.card(body, widgets, PAGE)
    for index in range(MAX_PROFILES):
        _row(rows, widgets, template, index)
    widgets["profiles:status"] = tx.text(rows, "", "status", wrap=True)
    w.column(rows, widgets["profiles:status"], padding=w.pad(t.SPACE_2, 0))
    _confirmation(widgets, template)


def page(owner, widgets, template):
    """The sidebar page of Omni Sprint and Third Person & FOV."""
    scroll, body = p.scrolling_body(owner, template)
    card(body, widgets, template)
    return scroll


def _row(rows, widgets, template, index):
    name = f"profiles:{index}"
    row = w.new("VerticalBox", rows)
    row.SetVisibility(w.enum("ESlateVisibility", "Collapsed"))
    widgets[name] = row
    w.column(rows, row)
    w.column(row, w.line(row, t.COLOR_HOVER, height=t.STROKE_THIN), padding=w.pad(t.SPACE_2, 0, 0))
    line = w.new("HorizontalBox", row)
    widgets[f"{name}:name"] = tx.text(line, "", "label", wrap=True)
    w.row(line, w.sized(line, widgets[f"{name}:name"], width=t.ROW_LABEL_WIDTH), valign="Center")
    for number, (part, kind, style) in enumerate(BUTTONS):
        w.row(line, b.button(line, widgets, f"{name}:{part}", kind, template, style),
              padding=w.pad(0, 0, 0, t.SPACE_3 if number else 0), valign="Center")
    w.row(line, w.new("Spacer", line), fill=True)
    w.row(line, commands._value(line, widgets, f"{name}:keyboard"), valign="Center")
    w.column(row, line, padding=w.pad(t.SPACE_3, 0, 0))
    widgets[f"{name}:values"] = tx.text(row, "", "hint", wrap=True)
    w.column(row, widgets[f"{name}:values"], padding=w.pad(t.SPACE_2, 0, t.SPACE_3))


def _confirmation(widgets, template):
    content = popup.build(widgets, POPUP, template)
    widgets[f"{POPUP}:text"] = tx.text(content, "", "body", wrap=True)
    w.column(content, widgets[f"{POPUP}:text"], padding=w.pad(t.SPACE_3, 0))
    line = w.new("HorizontalBox", content)
    for number, (part, style) in enumerate((("cancel", "secondary"), ("confirm", "primary"))):
        w.row(line, b.button(line, widgets, f"{POPUP}:{part}", "action", template, style),
              padding=w.pad(0, 0, 0, t.SPACE_4 if number else 0), valign="Center")
    w.column(content, line, padding=w.pad(t.SPACE_3, 0, 0), halign="Right")
    # CANCEL and DELETE stand for the pop-up's own CLOSE (mockup profils/4_supprimer.png); a click beside and Escape
    # still close it, as any pop-up's.
    for part in ("frame", "shadow"):
        widgets[f"popup:{POPUP}:close_{part}"].SetVisibility(w.enum("ESlateVisibility", "Collapsed"))
